arguments.file_text:
@namespace sv_efd14ccac0164035ab0a8dee97894f92.Components.Pages.Chat

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Services.Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    background: #3f0e40;
    color: #fff;
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

@namespace sv_efd14ccac0164035ab0a8dee97894f92.Components.Pages.Chat
@using sv_efd14ccac0164035ab0a8dee97894f92.Services
@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h3># @ChannelName</h3>
        <span class="area-desc">@ChannelDescription</span>
    </div>

    <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ThreadSummary="GetThreadSummary(msg.Id)"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
        }
    </div>

    <div class="compose-area">
        <textarea class="compose-input" @bind="NewMessageText" @bind:event="oninput"
                  placeholder="Message #@ChannelName" rows="2"
                  @onkeydown="HandleKeyDown" />
        <button class="send-btn" @onclick="HandleSend" disabled="@string.IsNullOrWhiteSpace(NewMessageText)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public bool HasMoreMessages { get; set; }

    private ElementReference _messageListRef;
    private string NewMessageText = "";
    private bool _loadingMore;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ScrollToBottom();
        }
    }

    private async Task ScrollToBottom()
    {
        try
        {
            await JS.InvokeVoidAsync("eval",
                "document.querySelector('.message-list')?.scrollTo(0, document.querySelector('.message-list')?.scrollHeight ?? 0)");
        }
        catch { /* ignore during prerender */ }
    }

    private async Task HandleScroll()
    {
        if (!HasMoreMessages || _loadingMore) return;

        try
        {
            var scrollTop = await JS.InvokeAsync<double>("eval",
                "document.querySelector('.message-list')?.scrollTop ?? 1");
            if (scrollTop < 50)
            {
                _loadingMore = true;
                await OnLoadMore.InvokeAsync();
                _loadingMore = false;
            }
        }
        catch { /* ignore during prerender */ }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
