@page "/chat"
@namespace sv_efd14ccac0164035ab0a8dee97894f92.Components.Pages.Chat
@using sv_efd14ccac0164035ab0a8dee97894f92.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(ThreadOpen ? "thread-open" : "")">
        @if (_activeChannel is not null)
        {
            <MessageArea Messages="_messages"
                         ChannelName="@_activeChannel.Name"
                         ChannelDescription="@_activeChannel.Description"
                         ThreadSummaries="_threadSummaries"
                         HasMoreMessages="_hasMoreMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (ThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private int _activeChannelId;
    private Channel? _activeChannel;
    private bool _hasMoreMessages = true;
    private const int PageSize = 30;

    // Thread state
    private int? _activeThreadRootId;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];
    private bool ThreadOpen => _activeThreadRootId.HasValue;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.Find(c => c.Id == channelId);
        _messages = [];
        _hasMoreMessages = true;
        _activeThreadRootId = null;

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count >= PageSize;

        await ChatService.MarkChannelReadAsync(channelId);
        await RefreshThreadSummaries();

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (!_hasMoreMessages || _activeChannel is null) return;

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize) _hasMoreMessages = false;
        _messages.InsertRange(0, older);
        await RefreshThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        await RefreshMessages();
    }

    private async Task OpenThread(int rootMessageId)
    {
        _activeThreadRootId = rootMessageId;
        _threadRootMessage = _messages.Find(m => m.Id == rootMessageId);
        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThread()
    {
        _activeThreadRootId = null;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeThreadRootId is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _activeThreadRootId);
        _threadReplies.Add(reply);
        await RefreshThreadSummaries();
    }

    private async Task RefreshMessages()
    {
        if (_activeChannel is null) return;
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count > 0 ? _messages.Count : PageSize);
    }

    private async Task RefreshThreadSummaries()
    {
        // Build thread summaries from messages that have replies
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToList();

        var summaries = new List<ThreadSummary>();
        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                summaries.Add(new ThreadSummary(rootId, thread.Count, thread[^1].SentAt));
            }
        }
        _threadSummaries = summaries;
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    position: fixed;
    top: 0;
    left: 0;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main.thread-open {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #999;
    font-size: 1.1rem;
}

